CREATE TABLE CORE.T_DIM_COST_ELEMENT_FISCAL_YEAR_AH_2 (
   ACCT_NR                             VARCHAR(20)     NOT NULL COMMENT 'Cost element Number. Same as the Account_2 Number of the corresponding Profit and Loss Account_2',
   CTRL_AREA_CD                        VARCHAR(5)      NOT NULL COMMENT 'Code of the Controlling Area ',
   FISCAL_YEAR                         NUMERIC         NOT NULL COMMENT 'A number that represents the fiscal year for which the accounting document is posted',
   CE_GROUP_LVL1_NR                    VARCHAR(20)     NOT NULL COMMENT 'Identifier of the Cost Element Group (a.k.a. KER Position) to which the CE Group lvl2 belongs according to the Standard  Hierarchy_2',
   CE_GROUP_LVL1_NAME_EN               VARCHAR(100)    COMMENT 'Long description of the  level 1 Cost Element Group in English',
   CE_GROUP_LVL1_NAME_DE               VARCHAR(100)    COMMENT 'Short description of the  level 1 Cost Element Group in German',
   CE_GROUP_LVL2_NR                    VARCHAR(20)     COMMENT 'Identifier of the Cost Element Group (a.k.a. KER Position) to which the CE Group lvl3 belongs according to the Standard  Hierarchy_2',
   CE_GROUP_LVL2_NAME_EN               VARCHAR(100)    COMMENT 'Long description of the level 2 Cost Element Group in English',
   CE_GROUP_LVL2_NAME_DE               VARCHAR(100)    COMMENT 'Short description of the  level 2 Cost Element Group in German',
   CE_GROUP_LVL3_NR                    VARCHAR(20)     COMMENT 'Identifier of the Cost Element Group (a.k.a. KER Position) to which this Cost Element belongs according to the Standard  Hierarchy_2',
   CE_GROUP_LVL3_NAME_EN               VARCHAR(100)    COMMENT 'Long description of the level 3 Cost Element Group in English',
   CE_GROUP_LVL3_NAME_DE               VARCHAR(100)    COMMENT 'Short description of the  level 3 Cost Element Group in German',
   CE_GROUP_LVL4_NR                    VARCHAR(20)     COMMENT 'Identifier of the Cost Element Group level 4 (a.k.a. KER Position) to which this Cost Element belongs according to the Standard  Hierarchy_2',
   CE_GROUP_LVL4_NAME_EN               VARCHAR(100)    COMMENT 'Long description of the level 4 Cost Element Group in English',
   CE_GROUP_LVL4_NAME_DE               VARCHAR(100)    COMMENT 'Short description of the  level 4 Cost Element Group in German',
   CHART_OF_ACCOUNTS_CD                VARCHAR(5)      COMMENT 'Unique Identifier of the Chart of Accounts',
   SHORT_NAME_EN                       VARCHAR(100)    COMMENT 'Short description of the Cost Element in English',
   LONG_NAME_EN                        VARCHAR(100)    COMMENT 'Long description of the Cost Element in English',
   SHORT_NAME_DE                       VARCHAR(100)    COMMENT 'Short description of the Cost Element in German',
   LONG_NAME_DE                        VARCHAR(100)    COMMENT 'Long description of the Cost Element in Gernam',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',   
   CONSTRAINT PK_T_DIM_COST_ELEMENT_FISCAL_YEAR_AH PRIMARY KEY (CTRL_AREA_CD, ACCT_NR, FISCAL_YEAR, CE_GROUP_LVL1_NR) NOT ENFORCED 
)  COMMENT = 'Table that describes and historizes the fiscal year alternative hierarchies of Cost Element Groups and their relationship to Cost Element';
